/*────────────────── 공용 부품: 매장 정보 카드 / 배지 / 태그 입력 ─────────────────*/

// 위치(핀) 배지 — 사진 위에 얹히는 파란 마커
function PinBadge() {
  return <span className="pin-badge">📍</span>;
}

// 알러지 등 강조용 배지
function Badge({ children }) {
