}

// 매장 정보 카드 (사진 + 이름/영업시간/주소/전화번호)
// onToggleFavorite을 넘기면 카드 오른쪽에 찜하기 버튼이 표시됩니다.
function StoreCard({ store, isFavorite, onToggleFavorite }) {
