// 메뉴 + 알러지 정보 카드 (신청 화면용)
function MenuCard({ items, allergies }) {
  return (
    <div className="menu-card">
      <div className="menu-card__top">
        <div className="menu-card__photo" />
        <ul className="menu-card__list">
