  const tone =
    status === "수령완료" || status === "등록됨"
      ? "status-badge--done"
      : status === "취소됨" || status === "마감됨"
      ? "status-badge--muted"
      : "status-badge--pending";
  return <span className={"status-badge " + tone}>{status}</span>;
}

