function SupportScreen({ onNavigate }) {
  const faqs = [
    {
      q: "도시락은 어떻게 신청하나요?",
      a: "홈 화면 지도에서 매장을 선택한 뒤 '도시락 조회' 화면에서 수령 시간을 입력하고 신청하기를 누르면 됩니다.",
